function validate([n]) {
  if (!Number.isInteger(n) || n < 1 || n > 10) return 'n is a whole number from 1 to 10.';
  if (n === 10) return 'n = 10 has 28,800 arrangements, more output than this app can hold (256 KiB); try n up to 9.';
  return null;
}

