function permute(n) {
  const result = [];
  const path = [];
  const used = new Array(n + 1).fill(false);

  function backtrack() {
    if (path.length === n) {
      result.push([...path]);
      return;
    }
    for (let value = 1; value <= n; value++) {
      if (used[value]) {
        continue;
      }
      if (path.length > 0 && path[path.length - 1] % 2 === value % 2) {
        continue;
      }
      used[value] = true;
      path.push(value);
      backtrack();
      path.pop();
      used[value] = false;
    }
  }

  backtrack();
  return result;
}

