function permute(n) {
  // Visit all n! orderings in lexicographic order with the next-permutation step and keep the alternating ones.
  const order = Array.from({ length: n }, (_, i) => i + 1);
  const result = [];
  for (;;) {
    let alternating = true;
    for (let i = 1; i < n; i++) if (order[i] % 2 === order[i - 1] % 2) alternating = false;
    if (alternating) result.push(order.slice());
    let i = n - 2;
    while (i >= 0 && order[i] > order[i + 1]) i--;
    if (i < 0) return result;
    let j = n - 1;
    while (order[j] < order[i]) j--;
    [order[i], order[j]] = [order[j], order[i]];
    for (let a = i + 1, b = n - 1; a < b; a++, b--) [order[a], order[b]] = [order[b], order[a]];
  }
}

