function generate(rand, size) {
  // n = 10 has 28,800 answers, more output than the app allows, so large inputs use n = 8 or 9.
  if (size === 'large') return [8 + Math.floor(rand() * 2)];
  return [1 + Math.floor(rand() * 7)];
}
